<?php
declare(strict_types=1);namespace App\Services;use App\Repositories\{AuditRepository,SecurityGroupRepository};use App\Security\Auth;use PDO;use RuntimeException;
final readonly class SecurityGroupService{public function __construct(private PDO $db,private SecurityGroupRepository $repo,private AuditRepository $audit){}public function save(array $in):int{$id=(int)($in['id']??0);$name=trim((string)($in['name']??''));if(strlen($name)<2||strlen($name)>100)throw new RuntimeException('Nombre de grupo inválido.');$old=$id?$this->repo->find($id):null;if($id&&!$old)throw new RuntimeException('Grupo no encontrado.');if($old&&$old['system_locked'])throw new RuntimeException('El grupo Superadministrador está protegido.');$admin=isset($in['is_admin']);$reseller=isset($in['is_reseller']);if($admin&&$reseller)throw new RuntimeException('Un grupo no puede ser administrativo y revendedor al mismo tiempo.');$sub=$reseller&&isset($in['allows_subresellers']);$description=substr(trim((string)($in['description']??'')),0,255)?:null;$permissions=array_values(array_unique(array_filter(array_map('intval',(array)($in['permission_ids']??[])),static fn($v)=>$v>0)));$valid=[];if($permissions){$marks=implode(',',array_fill(0,count($permissions),'?'));$s=$this->db->prepare("SELECT id FROM permissions WHERE id IN ({$marks})");$s->execute($permissions);$valid=array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN));}if($admin&&!$valid)throw new RuntimeException('Un grupo administrativo necesita al menos un permiso.');$this->db->beginTransaction();try{if($old){$this->db->prepare('UPDATE roles SET name=?,is_admin=?,is_reseller=?,allows_subresellers=?,description=? WHERE id=?')->execute([$name,$admin,$reseller,$sub,$description,$id]);}else{$slug=$this->slug($name).'-'.substr(bin2hex(random_bytes(4)),0,8);$this->db->prepare('INSERT INTO roles(name,slug,is_admin,is_reseller,allows_subresellers,description) VALUES(?,?,?,?,?,?)')->execute([$name,$slug,$admin,$reseller,$sub,$description]);$id=(int)$this->db->lastInsertId();}$this->db->prepare('DELETE FROM role_permissions WHERE role_id=?')->execute([$id]);$s=$this->db->prepare('INSERT INTO role_permissions(role_id,permission_id) VALUES(?,?)');foreach($valid as $permission)$s->execute([$id,$permission]);$this->db->commit();$this->audit->record('security_group.saved','role',$id,['name'=>$name,'admin'=>$admin,'reseller'=>$reseller,'permissions'=>count($valid)]);return $id;}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}public function delete(int $id):void{$g=$this->repo->find($id)??throw new RuntimeException('Grupo no encontrado.');if($g['system_locked'])throw new RuntimeException('El grupo Superadministrador no se puede eliminar.');$s=$this->db->prepare('SELECT COUNT(*) FROM user_roles WHERE role_id=?');$s->execute([$id]);if((int)$s->fetchColumn()>0)throw new RuntimeException('Mueve los usuarios a otro grupo antes de eliminarlo.');$this->db->prepare('DELETE FROM roles WHERE id=?')->execute([$id]);$this->audit->record('security_group.deleted','role',$id,['name'=>$g['name']]);}private function slug(string $v):string{return strtolower(trim((string)preg_replace('/[^A-Za-z0-9]+/','-',$v),'-'))?:'group';}}
